import { Mesh, PlaneGeometry, Group, Vector3 } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  // Root object
  const root = new ctx.THREE.Group();

  // Apply rotation & scale from config (position handled by adapter)
  const rot = config.rotation ?? { x: 0, y: 0, z: 0 };
  const scl = config.scale ?? { x: 1, y: 1, z: 1 };
  root.rotation.set(rot.x, rot.y, rot.z);
  root.scale.set(scl.x, scl.y, scl.z);

  // Atlas region – fallback to spec values
  const atlas = {
    x: 0,
    y: 0,
    width: 512,
    height: 320,
    ...(config.atlasRegion || {})
  };
  const aspect = atlas.width / atlas.height;

  // Geometry sized to atlas aspect ratio
  const geometry = new ctx.THREE.PlaneGeometry(aspect, 1);

  // Basic node material (transparent to allow alpha)
  const material = new ctx.THREE.MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    side: ctx.THREE.DoubleSide
  });

  // Mesh
  const mesh = new ctx.THREE.Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously and assign to material
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then(tex => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Billboard handler – aligns mesh to camera each frame if camera available
  const billboard = () => {
    if (ctx.camera && ctx.camera.position) {
      // Keep the plane facing the camera
      mesh.lookAt(ctx.camera.position);
    }
  };
  root.userData.handlers = {
    update: billboard
  };

  // Cleanup resources
  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();
    if (material.map && material.map.dispose) {
      material.map.dispose();
    }
    // Kill any GSAP timelines (none created here but safe)
    gsap.globalTimeline.clear();
    // Cleanup primitives if any were added (none for this node)
    if (root.userData.primitiveInstances) {
      root.userData.primitiveInstances.forEach(p => {
        if (p && p.cleanup) p.cleanup();
      });
    }
  };

  return root;
}
